import sys
from collections import defaultdict

sys.setrecursionlimit(400000)

def dfs(v, p, edges, sub_size):
    sub_size[v] = 1
    for u in edges[v]:
        if u == p:
            continue
        sub_size[v] += dfs(u, v, edges, sub_size)
    return sub_size[v]

def can_be_centroid(n, edges, sub_size):
    for v in range(1, n + 1):
        is_centroid = True
        for u in edges[v]:
            if sub_size[u] > n // 2:
                is_centroid = False
                break
        if is_centroid:
            continue
        # Check if replacing one edge can make it a centroid
        for u in edges[v]:
            if sub_size[u] <= n // 2:
                if sub_size[v] - sub_size[u] <= n // 2:
                    is_centroid = True
                    break
        if is_centroid:
            yield 1
        else:
            yield 0

def main():
    n = int(sys.stdin.readline().strip())
    edges = defaultdict(list)
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().strip().split())
        edges[u].append(v)
        edges[v].append(u)

    sub_size = [0] * (n + 1)
    dfs(1, -1, edges, sub_size)

    result = list(can_be_centroid(n, edges, sub_size))
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
